    def parse_order_status(self, status: Str) -> Str:
        statuses = {
            'open': 'open',
            'inactive': 'open',  # stop-limit order waiting for its trigger
            'filled': 'closed',
            'cancelled': 'canceled',
        }
        return self.safe_string(statuses, status, status)

    def parse_order_type(self, type: Str) -> Str:
        types = {
            'limit': 'limit',
            'market': 'market',
            'stop-limit': 'limit',
        }
        return self.safe_string(types, type, type)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        #
        # createOrder, cancelOrder, fetchOrder, fetchOrders
        #
        #     {
        #         "cancelReason": null,
        #         "clientOrderId": null,
        #         "cost": 15600.12,
        #         "createdAt": "2024-05-07T14:08:30.961Z",
        #         "feeAmount": 15.60012,
        #         "feeCurrency": "EUR",
        #         "filledAmount": 0.24,
        #         "id": "536ee1dc-528a-419e-9c00-5e04c010658d",
        #         "orderAmount": 0.35,
        #         "orderGroupId": null,
        #         "orderType": "limit",
        #         "postOnly": null,
        #         "price": 65000.5,
        #         "side": "buy",
        #         "status": "open",
        #         "stopPrice": 0,
        #         "symbol": "BTC/EUR",
        #         "timeInForce": "GTC",
        #         "updatedAt": "2024-05-07T14:09:02.310Z",
        #         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        #     }
        #
        marketId = self.safe_string(order, 'symbol')
        resolvedMarket = self.safe_market(marketId, market)
        timestamp = self.parse8601(self.safe_string(order, 'createdAt'))
        rawType = self.safe_string(order, 'orderType')
        fee = None
        feeCost = self.safe_number(order, 'feeAmount')
        if feeCost is not None:
            fee = {
                'cost': feeCost,
                'currency': self.safe_currency_code(self.safe_string(order, 'feeCurrency')),
            }
        return self.safe_order({
            'info': order,
            'id': self.safe_string(order, 'id'),
            'clientOrderId': self.safe_string(order, 'clientOrderId'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': self.parse8601(self.safe_string(order, 'updatedAt')),
            'symbol': resolvedMarket['symbol'],
            'type': self.parse_order_type(rawType),
            'timeInForce': self.safe_string(order, 'timeInForce'),
            'postOnly': self.safe_bool(order, 'postOnly'),
            'reduceOnly': None,
            'side': self.safe_string_lower(order, 'side'),
            # market orders are stored with a price of 0
            'price': self.omit_zero(self.safe_string(order, 'price')),
            'triggerPrice': self.omit_zero(self.safe_string(order, 'stopPrice')),
            'amount': self.safe_string(order, 'orderAmount'),
            'cost': self.safe_string(order, 'cost'),
            'average': None,
            'filled': self.safe_string(order, 'filledAmount'),
            'remaining': None,
            'status': self.parse_order_status(self.safe_string(order, 'status')),
            'fee': fee,
            'trades': None,
        }, resolvedMarket)

