    async def transfer(self, code: str, amount: float, fromAccount: str, toAccount: str, params: dict = {}) -> TransferEntry:
        """
        transfer currency internally between the bit2me wallet and the trading(pro) wallet

        https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/deposit/post
        https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/wallet/withdraw/post

        :param str code: unified currency code
        :param float amount: amount to transfer
        :param str fromAccount: 'funding'(the bit2me wallet) or 'spot'(the trading wallet)
        :param str toAccount: 'funding'(the bit2me wallet) or 'spot'(the trading wallet)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a [transfer structure](https://docs.ccxt.com/#/?id=transfer-structure)
        """
        await self.load_markets()
        currency = self.currency(code)
        accountsByType = self.safe_dict(self.options, 'accountsByType', {})
        fromId = self.safe_string(accountsByType, fromAccount, fromAccount)
        toId = self.safe_string(accountsByType, toAccount, toAccount)
        request = {
            'currency': currency['id'],
            'amount': self.currency_to_precision(code, amount),
        }
        response = None
        if (fromId == 'wallet') and (toId == 'trading'):
            response = await self.privatePostV1TradingWalletDeposit(self.extend(request, params))
        elif (fromId == 'trading') and (toId == 'wallet'):
            response = await self.privatePostV1TradingWalletWithdraw(self.extend(request, params))
        else:
            raise BadRequest(self.id + ' transfer() only supports transfers between the funding account (bit2me wallet) and the spot account (trading wallet)')
        #
        #     {
        #         "balance": 1350.5,
        #         "blockedBalance": 0,
        #         "createdAt": "2023-09-13T14:05:42.149Z",
        #         "currency": "EUR",
        #         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        #         "rawBalance": "1350.5",
        #         "rawBlockedBalance": "0",
        #         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        #     }
        #
        transfer = self.parse_transfer(response, currency)
        transfer['amount'] = amount
        transfer['fromAccount'] = fromAccount
        transfer['toAccount'] = toAccount
        return transfer

    async def fetch_transfers(self, code: Str = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[TransferEntry]:
        """
        fetch the history of movements between the bit2me wallet and the trading(pro) wallet

        https://api.bit2me.com/docs/pro/api-reference/funding/v1/trading/movement/get

        :param str [code]: unified currency code of the currency transferred
        :param int [since]: the earliest time in ms to fetch transfers for
        :param int [limit]: the maximum number of transfer structures to retrieve, default 100, max 100
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: the latest time in ms to fetch transfers for
        :param str [params.movementType]: 'deposit' or 'withdrawal', to fetch only one direction
        :returns dict[]: a list of [transfer structures](https://docs.ccxt.com/#/?id=transfer-structure)
        """
        await self.load_markets()
        currency = None
        request = {}
        if code is not None:
            currency = self.currency(code)
            request['currency'] = currency['id']
        if since is not None:
            request['from'] = self.iso8601(since)
        if limit is not None:
            request['limit'] = min(limit, 100)
        until, query = self.handle_param_integer(params, 'until')
        if until is not None:
            request['to'] = self.iso8601(until)
        response = await self.privateGetV1TradingMovement(self.extend(request, query))
        #
        #     [
        #         {
        #             "amount": 100,
        #             "createdAt": "2025-03-10T09:30:00.000Z",
        #             "currency": "EUR",
        #             "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        #             "movementType": "deposit",
        #             "serviceOrderName": "wallet",
        #             "status": "completed",
        #             "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        #         }
        #     ]
        #
        return self.parse_transfers(response, currency, since, limit)

    def parse_transfer(self, transfer: dict, currency: Currency = None) -> TransferEntry:
        #
        # transfer
        #
        #     {
        #         "balance": 1350.5,
        #         "blockedBalance": 0,
        #         "createdAt": "2023-09-13T14:05:42.149Z",
        #         "currency": "EUR",
        #         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
        #         "rawBalance": "1350.5",
        #         "rawBlockedBalance": "0",
        #         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
        #     }
        #
        # fetchTransfers
        #
        #     {
        #         "amount": 100,
        #         "createdAt": "2025-03-10T09:30:00.000Z",
        #         "currency": "EUR",
        #         "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
        #         "movementType": "deposit",
        #         "serviceOrderName": "wallet",
        #         "status": "completed",
        #         "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
        #     }
        #
        currencyId = self.safe_string(transfer, 'currency')
        movementType = self.safe_string(transfer, 'movementType')
        accountsById = self.safe_dict(self.options, 'accountsById', {})
        fromAccount = None
        toAccount = None
        id = None
        timestamp = None
        status = None
        if movementType is not None:
            # a movement from the historical list
            id = self.safe_string(transfer, 'id')
            timestamp = self.parse8601(self.safe_string(transfer, 'createdAt'))
            status = self.parse_transfer_status(self.safe_string(transfer, 'status'))
            wallet = self.safe_string(accountsById, 'wallet')
            trading = self.safe_string(accountsById, 'trading')
            fromAccount = wallet if (movementType == 'deposit') else trading
            toAccount = trading if (movementType == 'deposit') else wallet
        else:
            # the trading wallet returned by deposit/withdraw, createdAt is the wallet creation date
            status = 'ok'
        return {
            'info': transfer,
            'id': id,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'currency': self.safe_currency_code(currencyId, currency),
            'amount': self.safe_number(transfer, 'amount'),
            'fromAccount': fromAccount,
            'toAccount': toAccount,
            'status': status,
        }

    def parse_transfer_status(self, status: Str) -> Str:
        statuses = {
            'completed': 'ok',
            'pending': 'pending',
            'failed': 'failed',
            'cancelled': 'canceled',
        }
        return self.safe_string(statuses, status, status)

    def nonce(self) -> int:
        # the nonce must be a unix timestamp in milliseconds, within 5 seconds of the server clock
        return self.milliseconds()

    def sign(self, path: str, api: list[str] = ['public'], method: str = 'GET', params: dict = {}) -> dict:
        apiName = api[0]
        requestHeaders = None
        requestBody = None
        query = self.omit(params, self.extract_params(path))
        url = '/' + self.implode_params(path, params)
        isGetOrDelete = (method == 'GET') or (method == 'DELETE')
        if isGetOrDelete:
            if len(query) > 0:
                url += '?' + self.urlencode(query)
        if apiName == 'private':
            self.check_required_credentials()
            # https://api.bit2me.com/docs/guides/authentication
            # message = nonce:path[:compactJsonBody] -> sha256 (binary) -> hmac-sha512 (base64)
            nonce = str(self.nonce())
            message = nonce + ':' + url
            if not isGetOrDelete:
                # always send a json body, some http clients label an empty body as octet-stream and the gateway rejects it
                # an empty query is spelled out, php encodes an empty array as [] and would sign and post that instead of {}
                if len(query) > 0:
                    requestBody = self.json(query)
                else:
                    requestBody = '{}'
                message += ':' + requestBody
            digest = self.hash(self.encode(message), 'sha256', 'binary')
            signature = self.hmac(digest, self.encode(self.secret), hashlib.sha512, 'base64')
            requestHeaders = {
                'x-api-key': self.apiKey,
                'x-nonce': nonce,
                'api-signature': signature,
            }
            if requestBody is not None:
                requestHeaders['Content-Type'] = 'application/json'
        apiUrl = self.safe_string(self.urls['api'], apiName)
        if apiUrl is None:
            raise NotSupported(self.id + ' does not have a URL for ' + apiName + ' endpoints')
        fullUrl = apiUrl + url
        return {'url': fullUrl, 'method': method, 'body': requestBody, 'headers': requestHeaders}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response: object, requestHeaders: object, requestBody: object):
        if response is None:
            return None  # fallback to default error handler
        #
        #     {"statusCode":404,"error":"Not Found","message":"Market not found for symbol FOO/BAR","reqId":"9834b8a8-97b8-470d-ade2-3d31687c0723"}
        #     {"code":403,"description":"invalid credentials"}
        #     {"message":"Validation errors","errors":[{"code":"INVALID_REQUEST_PARAMETER","message":"Invalid parameter (symbol): Value is required but was not provided","in":"query","name":"symbol"}]}
        #     {"message":["type must be one of the following values: all, fiat, crypto"],"error":"Bad Request","statusCode":400}
        #     {"statusCode":412,"error":"Precondition Failed","message":"...","errorPayload":{"code":"ORDER_AMOUNT_LOWER_MARKET_MIN"}}
        #
        errorCode = self.safe_string_2(response, 'code', 'statusCode')
        errorsList = self.safe_list(response, 'errors')
        errorPayload = self.safe_dict(response, 'errorPayload', {})
        payloadCode = self.safe_string(errorPayload, 'code')
        if (errorCode is not None) or (errorsList is not None) or (payloadCode is not None):
            message = self.safe_string_n(response, ['message', 'description', 'error'])
            feedback = self.id + ' ' + body
            self.throw_exactly_matched_exception(self.exceptions['exact'], payloadCode, feedback)
            self.throw_broadly_matched_exception(self.exceptions['broad'], message, feedback)
            self.throw_broadly_matched_exception(self.exceptions['broad'], body, feedback)
            self.throw_exactly_matched_exception(self.exceptions['exact'], errorCode, feedback)
            raise ExchangeError(feedback)  # unknown message
        return None
